package com.bank.toposort;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.logging.Logger;

// Orders report stages with DFS post-order; three colors detect cycles.
public class ReportPipelineOrderer {

    private static final Logger log = Logger.getLogger(ReportPipelineOrderer.class.getName());

    private static final int WHITE = 0, GRAY = 1, BLACK = 2;

    private List<List<Integer>> adj;
    private int[] color;
    private Deque<Integer> stack;
    private boolean hasCycle;

    public List<Integer> order(int numStages, int[][] deps) {
        adj = new ArrayList<>();
        for (int i = 0; i < numStages; i++) adj.add(new ArrayList<>());
        for (int[] d : deps) {
            adj.get(d[0]).add(d[1]); // d[0] must run before d[1]
        }
        color = new int[numStages];
        stack = new ArrayDeque<>();
        hasCycle = false;

        for (int i = 0; i < numStages && !hasCycle; i++) {
            if (color[i] == WHITE) dfs(i);
        }
        if (hasCycle) {
            log.info("Cycle detected in pipeline; no valid order");
            return List.of();
        }
        List<Integer> result = new ArrayList<>();
        while (!stack.isEmpty()) result.add(stack.pop()); // reverse post-order
        log.info("Pipeline order: " + result);
        return result;
    }

    private void dfs(int u) {
        color[u] = GRAY;                 // on current path
        for (int v : adj.get(u)) {
            if (color[v] == GRAY) { hasCycle = true; return; } // back edge
            if (color[v] == WHITE) {
                dfs(v);
                if (hasCycle) return;
            }
        }
        color[u] = BLACK;                // finished
        stack.push(u);                   // post-order push
    }
}
