package com.bank.toposort;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class PipelineDemo {

    private static final Logger log = Logger.getLogger(PipelineDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Report Pipeline Ordering (DFS)");
        ReportPipelineOrderer orderer = new ReportPipelineOrderer();
        // 0 before 1, 1 before 2, 0 before 3
        int[][] deps = {{0, 1}, {1, 2}, {0, 3}};
        orderer.order(4, deps); // valid reverse post-order
    }
}
